drop function if exists submit_install_event(
  uuid, text, int, int, text, text, text, text, text, text, text, text, text, timestamptz
);

alter table projects
  add column if not exists bid_amount numeric,
  add column if not exists target_margin_pct numeric;

alter table time_shifts
  add constraint time_shifts_status_check
  check (status in ('open', 'submitted', 'approved', 'rejected'));

create policy "owner only financials" on vehicle_financials
      for all to authenticated
      using (
        (select role from profiles where id = auth.uid()) = 'owner'
      )
      with check (
        (select role from profiles where id = auth.uid()) = 'owner'
      );

create policy "owner supervisor drive sessions" on vehicle_drive_sessions
      for all to authenticated
      using (
        (select role from profiles where id = auth.uid())
          in ('owner','big_boss','supervisor','admin')
      )
      with check (
        (select role from profiles where id = auth.uid())
          in ('owner','big_boss','supervisor','admin')
      );

create policy profiles_select_authenticated on public.profiles
  for select to authenticated
  using (true);

create policy profiles_insert_self on public.profiles
  for insert to authenticated
  with check (id = auth.uid() or public.my_role_rank() >= 2);

create policy profiles_update_self_or_lead on public.profiles
  for update to authenticated
  using (id = auth.uid() or public.my_role_rank() >= 1)
  with check (id = auth.uid() or public.my_role_rank() >= 1);

create policy profiles_delete_supervisor on public.profiles
  for delete to authenticated
  using (public.my_role_rank() >= 2);

create trigger projects_create_staging_bays
  after insert on public.projects
  for each row execute function public.projects_create_staging_bays();

grant execute on function
  public.ai_spend_set_limits(integer, integer, text, boolean)
  to authenticated, service_role;

create trigger seed_opening_origin_pin
  before insert or update on project_openings
  for each row execute function public.seed_opening_origin_pin();

create trigger record_opening_pin_move
  after update of pin_x, pin_y, page_number on project_openings
  for each row execute function public.record_opening_pin_move();

create trigger guard_opening_pin_move
  before update of pin_x, pin_y, page_number on project_openings
  for each row execute function public.guard_opening_pin_move();

create trigger guard_opening_create_delete
  before insert or delete on project_openings
  for each row execute function public.guard_opening_create_delete();

create trigger guard_opening_removal
  before update of removed_at on project_openings
  for each row execute function public.guard_opening_removal();

create policy "issues_select_live" on issues
  for select to authenticated using (
    opening_id is null
    or exists (
      select 1 from project_openings o
      where o.id = issues.opening_id and o.removed_at is null
    )
  );

create policy "pin_moves_select_authenticated" on project_opening_pin_moves
  for select to authenticated using (
    exists (
      select 1 from project_openings o
      where o.id = project_opening_pin_moves.opening_id
        and o.removed_at is null
    )
  );

create trigger guard_test_account_profile_writes
  before insert or update or delete on public.profiles
  for each row execute function public.guard_test_account_profile_writes();

alter table time_shifts
  add constraint time_shifts_status_check
  check (status in ('open', 'submitted', 'approved', 'rejected', 'needs_finish'));

alter table opening_phases
  add column if not exists paused_at timestamptz,
  add column if not exists paused_seconds int not null default 0;

alter table time_shifts
  add constraint time_shifts_status_check
  check (status in ('open', 'submitted', 'approved', 'rejected', 'needs_finish', 'voided'));

create trigger unit_sessions_follow_shift
  after update on time_shifts
  for each row execute function unit_sessions_follow_shift();

create trigger unit_sessions_on_clock_in
  after insert on time_shifts
  for each row execute function unit_sessions_on_clock_in();

create trigger unit_sessions_follow_summon_helpers
  after insert or update on summon_helpers
  for each row execute function unit_sessions_follow_summon_helpers();

drop function if exists bind_package(
  uuid, uuid, text, text, text[], uuid, int, int, text, text
);

create policy app_feedback_select on app_feedback
  for select to authenticated using (
    author = auth.uid()
    or exists (
      select 1 from profiles
      where id = auth.uid() and role in ('owner', 'big_boss')
    )
  );

create policy app_feedback_update on app_feedback
  for update to authenticated using (
    exists (
      select 1 from profiles
      where id = auth.uid() and role in ('owner', 'big_boss')
    )
  ) with check (true);

create policy "projects_select_visible" on projects
  for select to authenticated using (
    is_test = false or _is_supervisor(auth.uid())
  );

create policy "app_feedback_select" on app_feedback
  for select to authenticated
  using (not public.is_partner_user() and (author = auth.uid() or exists ( select 1 from profiles where id = auth.uid() and role in ('owner', 'big_boss') )));

create policy "issues_select_live" on issues
  for select to authenticated
  using (not public.is_partner_user() and (opening_id is null or exists ( select 1 from project_openings o where o.id = issues.opening_id and o.removed_at is null )));

create policy "authenticated read" on opening_phases
  for select to authenticated
  using (not public.is_partner_user() and (true));

create policy "profiles_select_authenticated" on profiles
  for select to authenticated
  using (not public.is_partner_user() and (true));

create policy "pin_moves_select_authenticated" on project_opening_pin_moves
  for select to authenticated
  using (not public.is_partner_user() and (exists ( select 1 from project_openings o where o.id = project_opening_pin_moves.opening_id and o.removed_at is null )));

create policy "openings_select_live" on project_openings
  for select to authenticated
  using (not public.is_partner_user() and (removed_at is null));

create policy "summon_helpers_read" on summon_helpers
  for select to authenticated
  using (not public.is_partner_user() and (true));

create policy "authenticated full access" on task_sessions
  for all to authenticated
  using (not public.is_partner_user() and (true))
  with check (not public.is_partner_user() and (true));

create policy "authenticated full access" on time_shifts
  for all to authenticated
  using (not public.is_partner_user() and (true))
  with check (not public.is_partner_user() and (true));

create policy "unit_sessions_read" on unit_sessions
  for select to authenticated
  using (not public.is_partner_user() and (true));

create policy "owner supervisor drive sessions" on vehicle_drive_sessions
  for all to authenticated
  using (not public.is_partner_user() and ((select role from profiles where id = auth.uid()) in ('owner','big_boss','supervisor','admin')))
  with check (not public.is_partner_user() and ((select role from profiles where id = auth.uid()) in ('owner','big_boss','supervisor','admin')));

create policy "owner only financials" on vehicle_financials
  for all to authenticated
  using (not public.is_partner_user() and ((select role from profiles where id = auth.uid()) = 'owner'))
  with check (not public.is_partner_user() and ((select role from profiles where id = auth.uid()) = 'owner'));

create policy "projects_select_visible" on projects
  for select to authenticated using (
    is_test = false or _is_supervisor(auth.uid())
    or (
      public.is_partner_user()
      and exists (
        select 1 from partner_job_grants g
        where g.project_id = projects.id and g.partner_profile_id = auth.uid()
      )
    )
  );

alter table projects
  add column if not exists deleted_at timestamptz,
  add column if not exists deleted_by uuid references profiles(id) on delete set null;

create policy "projects_select_visible" on projects
  for select to authenticated using (
    (deleted_at is null or public.my_role_rank() >= 3)
    and (
      is_test = false or _is_supervisor(auth.uid())
      or (
        public.is_partner_user()
        and exists (
          select 1 from partner_job_grants g
          where g.project_id = projects.id and g.partner_profile_id = auth.uid()
        )
      )
    )
  );

alter table public.profiles
      add constraint profiles_language_check
      check (language in ('en', 'es'));

alter table projects add constraint projects_allowed_modes_check
  check (
    cardinality(allowed_modes) >= 1
    and allowed_modes <@ array['data', 'tracking']::text[]
  );

alter table attachments
  add column if not exists deleted_at timestamptz,
  add column if not exists deleted_by uuid references profiles(id) on delete set null;

create policy "projects_select_visible" on projects
  for select to authenticated using (
    (deleted_at is null or _is_supervisor(auth.uid()))
    and (
      is_test = false or _is_supervisor(auth.uid())
      or (
        public.is_partner_user()
        and exists (
          select 1 from partner_job_grants g
          where g.project_id = projects.id and g.partner_profile_id = auth.uid()
        )
      )
    )
  );

create policy "own shift read" on time_shift_edits
  for select to authenticated
  using (
    not public.is_partner_user()
    and exists (
      select 1 from time_shifts ts
       where ts.id = time_shift_edits.shift_id
         and ts.profile_id = auth.uid()
    )
  );

alter table project_openings add constraint project_openings_flag_kind_check
  check (
    flag_kind is null
    or flag_kind in ('wrong_size', 'mirrored', 'not_as_drawn', 'not_on_plans', 'other')
  );

create trigger guard_opening_flag_clear
  before update of flag_kind, flag_note on project_openings
  for each row execute function public.guard_opening_flag_clear();

alter table public.profiles
  add column if not exists can_see_costs boolean not null default false,
  add column if not exists can_see_pay boolean not null default false;

revoke all on function submit_install_event(
  uuid, text, int, int, text, text, text, text, text, text, text, text, text,
  timestamptz, uuid, int, uuid) from public, anon;

grant execute on function submit_install_event(
  uuid, text, int, int, text, text, text, text, text, text, text, text, text,
  timestamptz, uuid, int, uuid) to authenticated, service_role;

revoke all on function finish_unit(
  uuid, uuid, text, int, text, text, text, text, text, text, text, text, text,
  uuid, int, uuid) from public, anon;

grant execute on function finish_unit(
  uuid, uuid, text, int, text, text, text, text, text, text, text, text, text,
  uuid, int, uuid) to authenticated, service_role;

create trigger project_openings_assignment_log
  after update of assigned_to on project_openings
  for each row execute function public.trg_opening_assignment_event();

alter table public.profiles
  add column if not exists retired_at timestamptz,
  add column if not exists retired_by uuid references public.profiles(id) on delete set null;

create policy "project_documents_select" on project_documents
  for select to authenticated
  using (
    not public.is_partner_user()
    and (not money or public.can_see_costs(auth.uid()))
    and exists (
      select 1 from public.projects p where p.id = project_documents.project_id
    )
  );

alter table projects
  add column if not exists materials_finalized_at timestamptz,
  add column if not exists materials_finalized_by uuid;

create policy custom_units_read on public.custom_work_units for select to authenticated using(not public.is_partner_user() and public.custom_work_internal() and (
  (project_id is null and (created_by=auth.uid() or public._is_lead(auth.uid()))) or
  exists(select 1 from public.projects p where p.id=project_id and p.deleted_at is null)
));

create policy custom_sessions_read on public.custom_work_sessions for select to authenticated using(not public.is_partner_user() and public.custom_work_internal() and (
  (project_id is null and (profile_id=auth.uid() or public._is_lead(auth.uid()))) or
  exists(select 1 from public.projects p where p.id=project_id and p.deleted_at is null)
));

create policy custom_history_read on public.custom_work_history for select to authenticated using(not public.is_partner_user() and public.custom_work_internal() and (
  (project_id is null and (actor_id=auth.uid() or public._is_lead(auth.uid()))) or
  exists(select 1 from public.projects p where p.id=project_id and p.deleted_at is null)
));

create policy pay_rates_select on public.pay_rates for select to authenticated using (
  not public.is_partner_user() and public.can_see_pay(auth.uid())
  and exists (select 1 from profiles where id = auth.uid()
    and access_revoked_at is null and retired_at is null)
);

create policy crew_records_read on public.crew_work_records for select to authenticated using (
  not public.is_partner_user() and public.custom_work_internal() and exists(select 1 from public.projects p where p.id=project_id and p.deleted_at is null)
);

create policy ai_field_actions_read on public.ai_field_actions for select to authenticated using (
  not public.is_partner_user() and public.custom_work_internal() and (profile_id = auth.uid() or public._is_supervisor(auth.uid()))
  and (project_id is null or exists (select 1 from public.projects p where p.id = project_id and p.deleted_at is null))
);

create policy ai_field_jobs_read on public.ai_field_jobs for select to authenticated using (
  not public.is_partner_user() and public.custom_work_internal() and (created_by = auth.uid() or public._is_lead(auth.uid()))
  and exists (select 1 from public.projects p where p.id = project_id and p.deleted_at is null)
);

create trigger ai_clock_epoch_legacy_update after update on public.unit_sessions for each row
  when (old.profile_id is distinct from new.profile_id or old.ended_at is distinct from new.ended_at or old.opening_id is distinct from new.opening_id)
  execute function public._ai_bump_clock_epoch('profile_id');

create trigger ai_clock_epoch_task_update after update on public.task_sessions for each row
  when (old.profile_id is distinct from new.profile_id or old.ended_at is distinct from new.ended_at or old.state is distinct from new.state)
  execute function public._ai_bump_clock_epoch('profile_id');

create trigger ai_clock_epoch_phase_update after update on public.opening_phases for each row
  when (old.started_by is distinct from new.started_by or old.status is distinct from new.status or old.paused_at is distinct from new.paused_at)
  execute function public._ai_bump_clock_epoch('started_by');

create policy daily_log_contributions_read on public.daily_log_contributions for select to authenticated using (
  not public.is_partner_user() and public.can_file_daily_log()
  and not exists (select 1 from public.profiles p where p.id = auth.uid() and p.retired_at is not null)
);

create policy daily_log_contribution_photos_read on public.daily_log_contribution_photos for select to authenticated using (
  not public.is_partner_user() and public.can_file_daily_log()
  and not exists (select 1 from public.profiles p where p.id = auth.uid() and p.retired_at is not null)
);

create policy "projects_select_visible" on projects
  for select to authenticated using (
    (deleted_at is null or _is_supervisor(auth.uid()))
    and (
      is_test = false or _is_supervisor(auth.uid())
      or (
        public.is_partner_user()
        and exists (
          select 1 from partner_job_grants g
          where g.project_id = projects.id and g.partner_profile_id = auth.uid()
        )
      )
      or (
        is_test
        and public.is_test_profile(auth.uid())
        and public.custom_work_internal()
        and public.is_sandbox_project(projects.id)
      )
    )
  );

create policy "projects_select_visible" on projects
  for select to authenticated using (
    (deleted_at is null or _is_supervisor(auth.uid()))
    and (
      (
        not public.is_partner_user()
        and (
          is_test = false or _is_supervisor(auth.uid())
          or (
            is_test
            and public.is_test_profile(auth.uid())
            and public.custom_work_internal()
            and public.is_sandbox_project(projects.id)
          )
        )
      )
      or (
        public.is_partner_user()
        and deleted_at is null
        and public.partner_has_job_grant(projects.id)
      )
    )
  );

create policy "projects_update" on projects
  for update to authenticated
  using (deleted_at is null and not public.is_partner_user())
  with check (not public.is_partner_user());

alter table public.profiles
      add constraint profiles_ui_design_check
      check (ui_design in ('classic', 'new'));

create trigger project_bill_to_default
  after insert on public.projects
  for each row execute function public.project_bill_to_default();

revoke all on function public.file_daily_log(
  uuid, date, text, text, text, jsonb, text, bigint, boolean, text[], jsonb, text, jsonb, text, text,
  jsonb, text[], integer, text, integer, integer, integer, text
) from public, anon;

grant execute on function public.file_daily_log(
  uuid, date, text, text, text, jsonb, text, bigint, boolean, text[], jsonb, text, jsonb, text, text,
  jsonb, text[], integer, text, integer, integer, integer, text
) to authenticated;

create trigger work_unit_fact_binding_epoch_update after update on public.custom_work_units
  for each row when (old.project_id is distinct from new.project_id or old.opening_id is distinct from new.opening_id)
  execute function public._work_unit_fact_bump_epoch();

create trigger work_unit_fact_opening_epoch_update after update on public.project_openings
  for each row when (old.removed_at is distinct from new.removed_at or old.project_id is distinct from new.project_id)
  execute function public._work_unit_fact_bump_epoch();

create trigger work_unit_fact_project_epoch_update after update on public.projects
  for each row when (old.deleted_at is distinct from new.deleted_at)
  execute function public._work_unit_fact_bump_epoch();
